const body = $input.first().json.body || $input.first().json;
const alertName = body.commonLabels?.alertname || body.title || body.alert_name || 'Unknown Alert';
const severity = body.commonLabels?.severity || body.severity || 'warning';
const description = body.commonAnnotations?.description || body.message || body.body || JSON.stringify(body);
const service = body.commonLabels?.service || body.service || body.monitor || 'unknown';
return [{ json: { alert_name: alertName, severity, description, service } }];

const ctx = $input.first().json;
const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 4096,
  messages: [{
    role: 'user',
    content: 'You are an SRE investigating a production alert.

'      + 'Provide your response in EXACTLY this format:
'      + 'SUMMARY: [one sentence describing the likely root cause and recommended action]
'      + '---
'      + '[full detailed investigation including:
'      + '1. Likely root cause
'      + '2. Impact assessment (users affected, severity)
'      + '3. Immediate mitigation steps
'      + '4. Recommended follow-up actions]

'      + 'Alert name: ' + ctx.alert_name + '
'      + 'Severity: ' + ctx.severity + '
'      + 'Service: ' + ctx.service + '
'      + 'Description: ' + ctx.description
  }]
};
return [{ json: requestBody }];

const alert = $('Normalize Alert').first().json;
const claudeText = $input.first().json.content[0].text;
// Parse SUMMARY and details
let summary = 'Production alert: ' + alert.alert_name + ' on ' + alert.service + '.';
let details = claudeText;
const parts = claudeText.split(/^---$/m);
if (parts.length >= 2) {
  const match = parts[0].trim().match(/^SUMMARY:\s*(.+)/i);
  if (match) summary = match[1].trim();
  details = parts.slice(1).join('---').trim();
}
const issueBody = '> \uD83E\uDD16 **This is an automated message from the DevLLMOps AI Agent**\n\n'
  + '**' + summary + '**\n\n'
  + '<details>\n<summary>View full investigation</summary>\n\n'
  + '## Alert Details\n\n'
  + '| Field | Value |\n|---|---|\n'
  + '| **Alert** | ' + alert.alert_name + ' |\n'
  + '| **Severity** | ' + alert.severity + ' |\n'
  + '| **Service** | ' + alert.service + ' |\n\n'
  + '## Agent Investigation\n\n'
  + details + '\n\n'
  + '</details>';
return [{ json: {
  title: '[ALERT] ' + alert.alert_name,
  body: issueBody,
  labels: ['incident', 'intent']
} }];
